    </div>
  );
};

import React from 'react';
import { ConfusionValues, Metric } from '../types';

interface ConfusionMatrixProps {
  values: ConfusionValues;
  activeMetric: Metric | null;
}

export const ConfusionMatrix: React.FC<ConfusionMatrixProps> = ({ values, activeMetric }) => {
  const getCellClass = (type: keyof ConfusionValues) => {
    const base = "relative flex flex-col justify-center items-center p-4 min-h-[100px] rounded-xl border transition-all duration-300 cubic-bezier(0.4, 0, 0.2, 1) cursor-default select-none";

    let colorClass = "";
    switch (type) {
      case 'tp': colorClass = "bg-emerald-500/10 border-emerald-500/25 text-emerald-400"; break;
      case 'tn': colorClass = "bg-blue-400/10 border-blue-400/25 text-blue-400"; break;
      case 'fp': colorClass = "bg-orange-500/10 border-orange-500/25 text-orange-500"; break;
      case 'fn': colorClass = "bg-rose-500/10 border-rose-500/25 text-rose-500"; break;
    }

    let stateClass = "";
    if (activeMetric) {
      if (activeMetric.highlight.includes(type)) {
        stateClass = "scale-[1.05] z-10 shadow-[0_0_24px_rgba(255,255,255,0.06)]";
      } else if (activeMetric.dim.includes(type)) {
        stateClass = "opacity-25 scale-[0.97] blur-[1px]";
      }
    }

    return `${base} ${colorClass} ${stateClass}`;
  };

  const labels = {
    tp: 'Correctly caught',
    fn: 'Missed',
    fp: 'False alarm',
    tn: 'Correctly ignored'
  };

  return (
    <div className="relative">
      <div className="text-center font-semibold text-[0.82rem] uppercase tracking-[0.12em] text-[#8892a8] mb-2.5">
        Predicted
      </div>

      <div className="absolute -left-8 top-1/2 -translate-y-1/2 -rotate-90 origin-center whitespace-nowrap font-semibold text-[0.82rem] uppercase tracking-[0.12em] text-[#8892a8]">
        Actual
      </div>

      <div className="grid grid-cols-[auto_1fr_1fr] grid-rows-[auto_1fr_1fr] gap-1 ml-8">
        {/* Header Row */}
        <div className="w-0 h-0"></div> {/* Corner */}
        <div className="flex items-center justify-center p-2 font-mono-plex text-xs font-semibold text-[#8892a8]">Positive</div>
        <div className="flex items-center justify-center p-2 font-mono-plex text-xs font-semibold text-[#8892a8]">Negative</div>

        {/* Row 1: Actual Positive */}
        <div className="flex items-center justify-center p-2 font-mono-plex text-xs font-semibold text-[#8892a8]">Positive</div>

        {/* Cells */}
        <div className={getCellClass('tp')}>
          <div className="font-mono-plex text-[0.72rem] font-semibold tracking-widest uppercase mb-1 opacity-90">TP</div>
          <div className="font-serif-display text-[2.2rem] leading-none">{values.tp}</div>
          <div className="text-[0.72rem] mt-1 opacity-80">{labels.tp}</div>
        </div>

        <div className={getCellClass('fn')}>
          <div className="font-mono-plex text-[0.72rem] font-semibold tracking-widest uppercase mb-1 opacity-90">FN</div>
          <div className="font-serif-display text-[2.2rem] leading-none">{values.fn}</div>
          <div className="text-[0.72rem] mt-1 opacity-80">{labels.fn}</div>
        </div>

        {/* Row 2: Actual Negative */}
        <div className="flex items-center justify-center p-2 font-mono-plex text-xs font-semibold text-[#8892a8]">Negative</div>

        <div className={getCellClass('fp')}>
          <div className="font-mono-plex text-[0.72rem] font-semibold tracking-widest uppercase mb-1 opacity-90">FP</div>
          <div className="font-serif-display text-[2.2rem] leading-none">{values.fp}</div>
          <div className="text-[0.72rem] mt-1 opacity-80">{labels.fp}</div>
        </div>

        <div className={getCellClass('tn')}>
          <div className="font-mono-plex text-[0.72rem] font-semibold tracking-widest uppercase mb-1 opacity-90">TN</div>
          <div className="font-serif-display text-[2.2rem] leading-none">{values.tn}</div>
          <div className="text-[0.72rem] mt-1 opacity-80">{labels.tn}</div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { ConfusionValues, Metric } from '../types';
import { METRICS } from '../constants';

interface MetricsPanelProps {
  values: ConfusionValues;
  activeMetricId: string | null;
  onSelect: (id: string) => void;
}

export const MetricsPanel: React.FC<MetricsPanelProps> = ({ values, activeMetricId, onSelect }) => {
  return (
    <div className="flex flex-col gap-4">
      {METRICS.map((m) => {
        const isActive = activeMetricId === m.id;
        const den = m.den(values);
        const val = den === 0 ? '—' : (m.num(values) / den * 100).toFixed(1) + '%';

        return (
          <button
            key={m.id}
            onClick={() => onSelect(m.id)}
            className={`
              relative text-left group overflow-hidden rounded-xl border p-4 pl-5 transition-all duration-200
              ${isActive 
                ? 'bg-[#1f2330] border-[#ffffff33]' 
                : 'bg-[#181b24] border-[#2a2f3e] hover:border-[#444]'
              }
            `}
          >
            {/* Active Indicator Bar */}
            <div 
              className={`absolute left-0 top-0 bottom-0 w-[3px] transition-colors duration-200 ${isActive ? 'bg-emerald-400' : 'bg-[#8892a8]'}`}
            />

            <div className="font-bold text-[0.95rem] mb-0.5 text-[#e2e8f0]">{m.name}</div>
            <div className="font-mono-plex text-[0.78rem] text-[#8892a8] mb-1.5">{m.formula}</div>

            <div className="flex items-baseline gap-2.5">
              <div className="font-serif-display text-[1.6rem] text-emerald-400 leading-none">{val}</div>
              <div className="text-[0.82rem] text-[#8892a8] leading-[1.45]">
                {m.plain}
              </div>
            </div>
          </button>
        );
      })}
    </div>
  );
};

import React, { useMemo } from 'react';
import { ConfusionValues, Metric } from '../types';

interface DotsVisualizerProps {
  values: ConfusionValues;
  activeMetric: Metric | null;
}

export const DotsVisualizer: React.FC<DotsVisualizerProps> = ({ values, activeMetric }) => {

  const dots = useMemo(() => {
    const total = values.tp + values.tn + values.fp + values.fn;
    // Cap visual dots to ~200 for performance and layout aesthetics if total is huge
    const scale = total > 200 ? 200 / total : 1;

    const types: (keyof ConfusionValues)[] = ['tp', 'fp', 'fn', 'tn'];
    const result: { type: keyof ConfusionValues; isDim: boolean }[] = [];

    types.forEach(type => {
      const count = Math.round(values[type] * scale);
      const isDim = activeMetric ? !activeMetric.dotHL(type) : false;
      for (let i = 0; i < count; i++) {
        result.push({ type, isDim });
      }
    });
    return result;
  }, [values, activeMetric]);

  const getColor = (type: keyof ConfusionValues) => {
    switch(type) {
      case 'tp': return 'bg-emerald-400';
      case 'tn': return 'bg-blue-400';
      case 'fp': return 'bg-orange-500';
      case 'fn': return 'bg-rose-500';
    }
  };

  return (
    <div className="mt-10">
      <h2 className="text-2xl mb-1 text-white">Every Prediction, Visualized</h2>
      <p className="text-[#8892a8] text-sm mb-4 font-light">Each dot is one sample. Highlighted dots are used by the selected metric.</p>

      <div className="bg-[#181b24] border border-[#2a2f3e] rounded-[14px] p-6 flex flex-wrap gap-[6px] content-start min-h-[80px]">
        {dots.map((d, i) => (
          <div
            key={i}
            className={`
              w-[18px] h-[18px] rounded-full transition-all duration-300
              ${getColor(d.type)}
              ${d.isDim ? 'opacity-15 scale-75 grayscale' : 'opacity-100 scale-100'}
            `}
          />
        ))}
      </div>

      <div className="flex flex-wrap gap-x-5 gap-y-2 mt-3 ml-1">
        {[
          { label: 'True Positive', color: 'bg-emerald-400' },
          { label: 'True Negative', color: 'bg-blue-400' },
          { label: 'False Positive', color: 'bg-orange-500' },
          { label: 'False Negative', color: 'bg-rose-500' },
        ].map((item) => (
          <span key={item.label} className="flex items-center gap-1.5 text-xs text-[#8892a8]">
            <span className={`w-2.5 h-2.5 rounded-full ${item.color}`}></span>
            {item.label}
          </span>
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ConfusionValues } from './types';
import { SCENARIOS, METRICS } from './constants';
import { CustomPanel } from './components/CustomPanel';
import { ConfusionMatrix } from './components/ConfusionMatrix';
import { MetricsPanel } from './components/MetricsPanel';
import { DotsVisualizer } from './components/DotsVisualizer';
import { Pencil } from 'lucide-react';

export default function App() {
  const [activeScenarioId, setActiveScenarioId] = useState<string>('balanced');
  const [customValues, setCustomValues] = useState<ConfusionValues>({ tp: 40, fp: 10, fn: 10, tn: 40 });
  const [activeMetricId, setActiveMetricId] = useState<string | null>(null);

  // Derive current values based on scenario
  const currentValues: ConfusionValues = activeScenarioId === 'custom' 
    ? customValues 
    : SCENARIOS[activeScenarioId];

  const activeMetric = activeMetricId ? METRICS.find(m => m.id === activeMetricId) || null : null;

  const handleScenarioChange = (id: string) => {
    setActiveScenarioId(id);
    if (id === 'custom') {
       // When switching to custom, populate it with current static values if needed, 
       // but here we keep custom independent or pre-filled.
       // Let's reset custom to balanced start if it was empty, 
       // or just keep previous custom state. Keeping state is better UX.
    }
  };

  const handleCustomChange = (key: keyof ConfusionValues, val: number) => {
    setCustomValues(prev => ({ ...prev, [key]: val }));
  };

  const handleMetricSelect = (id: string) => {
    setActiveMetricId(prev => prev === id ? null : id);
  };

  return (
    <div className="min-h-screen bg-[#0f1117] text-[#e2e8f0] pb-16">
      <div className="max-w-[960px] mx-auto px-6 py-10">

        {/* Header */}
        <h1 className="text-4xl text-white mb-1 tracking-tight">Classification Metrics, Demystified</h1>
        <p className="text-[#8892a8] text-[1.05rem] font-light mb-10">
          Click a scenario, then click any metric to see which cells it uses.
        </p>

        {/* Scenario Selector */}
        <div className="flex flex-wrap gap-2.5 mb-8">
          {Object.values(SCENARIOS).map((s) => (
            <button
              key={s.id}
              onClick={() => handleScenarioChange(s.id)}
              className={`
                px-4 py-2 rounded-lg text-sm transition-all border
                ${activeScenarioId === s.id 
                  ? 'bg-[#1f2330] border-emerald-400/50 text-white shadow-[0_0_12px_rgba(52,211,153,0.15)]' 
                  : 'bg-[#181b24] border-[#2a2f3e] text-[#8892a8] hover:border-[#555] hover:text-[#e2e8f0]'
                }
              `}
            >
              {s.name} {s.id === 'custom' && <Pencil className="inline w-3 h-3 ml-1 mb-0.5"/>}
            </button>
          ))}
        </div>

        {/* Custom Sliders (Conditional) */}
        {activeScenarioId === 'custom' && (
          <CustomPanel values={customValues} onChange={handleCustomChange} />
        )}

        {/* Main Grid Layout */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">

          {/* Left: Matrix */}
          <ConfusionMatrix values={currentValues} activeMetric={activeMetric} />

          {/* Right: Metrics List */}
          <MetricsPanel 
            values={currentValues} 
            activeMetricId={activeMetricId} 
            onSelect={handleMetricSelect} 
          />

        </div>

        {/* Insight Box */}
        <div className="mt-8 bg-gradient-to-br from-emerald-500/5 to-blue-500/5 border border-[#2a2f3e] rounded-xl p-6 text-[0.92rem] leading-relaxed text-[#e2e8f0]">
          {activeMetric 
            ? activeMetric.insight(currentValues)
            : "Click a metric above to see how it's calculated and when it matters."
          }
        </div>

        {/* Dots Visualization */}
        <DotsVisualizer values={currentValues} activeMetric={activeMetric} />

      </div>
    </div>
  );
}

